```sparql
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?film ?filmLabel ?director ?directorName ?birthDate
WHERE {
  VALUES ?film { dbr:The_Sawdust_Paradise dbr:The_Kaiser's_Shadow }

  # director (prefer dbp:director, fallback to dbo:director)
  { ?film dbp:director ?director } UNION { ?film dbo:director ?director }

  # film label (optional)
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER (lang(?filmLabel) = "en") }

  # director name (prefer dbp:name, fallback to rdfs:label)
  OPTIONAL { ?director dbp:name ?directorName . }
  OPTIONAL {
    ?director rdfs:label ?directorName .
    FILTER (lang(?directorName) = "en")
  }

  # director birth date (prefer dbp:birthDate, fallback to dbo:birthDate)
  OPTIONAL { ?director dbp:birthDate ?birthDate . }
  OPTIONAL { ?director dbo:birthDate ?birthDate . }
}
LIMIT 100
